insert into public.shabads (order_index, title, lines, deadline_days) values (0, 'ਵਡਹੰਸੁਮਹਲਾ੪॥', '[{"gurmukhi":"ਮੇਰਾਹਰਿਪ੍ਰਭੁਸੁੰਦਰੁਮੈਸਾਰਨਜਾਣੀ॥","meaning":"ਮੇਰਾ ਹਰੀ ਪ੍ਰਭੂ ਸੋਹਣਾ ਹੈ (ਪਰ) ਮੈਂ (ਉਸ ਦੇ ਸੁਹਣੱਪ ਦੀ) ਕਦਰ ਨਾਹ ਜਾਤੀ,"},{"gurmukhi":"ਹਉਹਰਿਪ੍ਰਭਛੋਡਿਦੂਜੈਲੋਭਾਣੀ॥੧॥","meaning":"(ਤੇ) ਮੈਂ ਉਸ ਹਰੀ ਨੂੰ ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਛੱਡ ਕੇ ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਹੀ ਫਸੀ ਰਹੀ ।੧।"},{"gurmukhi":"ਹਉਕਿਉਕਰਿਪਿਰਕਉਮਿਲਉਇਆਣੀ॥","meaning":"ਮੈਂ ਮੂਰਖ ਹਾਂ, ਮੈਂ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਕਿਵੇਂ ਮਿਲ ਸਕਦੀ ਹਾਂ?"},{"gurmukhi":"ਜੋਪਿਰਭਾਵੈਸਾਸੋਹਾਗਣਿਸਾਈਪਿਰਕਉਮਿਲੈਸਿਆਣੀ॥੧॥ਰਹਾਉ॥","meaning":"ਜੇਹੜੀ (ਜੀਵ-ਇਸਤ੍ਰੀ) ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਪਸੰਦ ਆਉਂਦੀ ਹੈ, ਉਹ ਭਾਗਾਂ ਵਾਲੀ ਹੈ, ਉਹੀ ਅਕਲ ਵਾਲੀ ਹੈ, ਉਹੀ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਮਿਲ ਸਕਦੀ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਮੈਵਿਚਿਦੋਸਹਉਕਿਉਕਰਿਪਿਰੁਪਾਵਾ॥","meaning":"ਮੇਰੇ ਅੰਦਰ (ਅਨੇਕਾਂ) ਐਬ ਹਨ (ਜਿਨ੍ਹਾਂ ਕਰ ਕੇ) ਮੈਂ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਮਿਲ ਨਹੀਂ ਸਕਦੀ ।"},{"gurmukhi":"ਤੇਰੇਅਨੇਕਪਿਆਰੇਹਉਪਿਰਚਿਤਿਨਆਵਾ॥੨॥","meaning":"ਹੇ ਪ੍ਰਭੂ-ਪਤੀ! ਤੇਰੇ ਨਾਲ ਪਿਆਰ ਕਰਨ ਵਾਲੇ ਅਨੇਕਾਂ ਹੀ ਹਨ, ਮੈਂ ਤੇਰੇ ਚਿੱਤ ਵਿਚ ਨਹੀਂ ਆ ਸਕਦੀ ।੨।"},{"gurmukhi":"ਜਿਨਿਪਿਰੁਰਾਵਿਆਸਾਭਲੀਸੁਹਾਗਣਿ॥","meaning":"ਜਿਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਨੇ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਵਸਾ ਲਿਆ, ਉਹ ਨੇਕ ਹੈ, ਉਹ ਭਾਗਾਂ ਵਾਲੀ ਹੈ, ਉਸ ਸੁਹਾਗਣ ਵਾਲੇ ਗੁਣ ਮੇਰੇ ਅੰਦਰ ਨਹੀਂ ਹਨ ।"},{"gurmukhi":"ਸੇਮੈਗੁਣਨਾਹੀਹਉਕਿਆਕਰੀਦੁਹਾਗਣਿ॥੩॥","meaning":"ਮੈਂ ਛੁੱਟੜ (ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਮਿਲਣ ਲਈ) ਕੀਹ ਕਰ ਸਕਦੀ ਹਾਂ? ।੩।"},{"gurmukhi":"ਨਿਤਸੁਹਾਗਣਿਸਦਾਪਿਰੁਰਾਵੈ॥","meaning":"ਜੇਹੜੀ ਜੀਵ-ਇਸਤ੍ਰੀ ਸਦਾ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਵਸਾਈ ਰੱਖਦੀ ਹੈ ਉਹ ਸਦਾ ਭਾਗਾਂ ਵਾਲੀ ਹੈ ।"},{"gurmukhi":"ਮੈਕਰਮਹੀਣਕਬਹੀਗਲਿਲਾਵੈ॥੪॥","meaning":"ਮੇਰੇ ਵਰਗੀ ਮੰਦ-ਭਾਗਣ ਨੂੰ ਉਹ ਕਦੇ (ਕਿਸਮਤ ਨਾਲ) ਹੀ ਆਪਣੇ ਗਲ ਨਾਲ ਲਾਂਦਾ ਹੈ ।੪।"},{"gurmukhi":"ਤੂਪਿਰੁਗੁਣਵੰਤਾਹਉਅਉਗੁਣਿਆਰਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ-ਪਤੀ! ਤੂੰ ਗੁਣਾਂ ਨਾਲ ਭਰਪੂਰ ਹੈਂ, ਪਰ ਮੈਂ ਅਉਗਣਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਹਾਂ ।"},{"gurmukhi":"ਮੈਨਿਰਗੁਣਬਖਸਿਨਾਨਕੁਵੇਚਾਰਾ॥੫॥੨॥","meaning":"(ਤੇਰੇ ਦਰ ਤੇ ਹੀ ਅਰਦਾਸ ਹੈ—) ਮੈਨੂੰ ਗੁਣ-ਹੀਨ ਨਿਮਾਣੇ ਨਾਨਕ ਨੂੰ ਬਖ਼ਸ਼ ਲੈ (ਤੇ, ਆਪਣੇ ਨਾਮ ਦੀ ਦਾਤਿ ਦੇਹ ।੫।੨।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (8, 'ੴਸਤਿਨਾਮੁਕਰਤਾਪੁਰਖੁਨਿਰਭਉਨਿਰਵੈਰੁਅਕਾਲਮੂਰਤਿਅਜੂਨੀਸੈਭੰਗੁਰਪ੍ਰਸਾਦਿ॥', '[{"gurmukhi":"ਰਾਗੁਜੈਜਾਵੰਤੀਮਹਲਾ੯॥","meaning":""},{"gurmukhi":"ਰਾਮੁਸਿਮਰਿਰਾਮੁਸਿਮਰਿਇਹੈਤੇਰੈਕਾਜਿਹੈ॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ (ਦਾ ਨਾਮ) ਸਿਮਰਿਆ ਕਰ, ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਕਰ । ਇਹ (ਸਿਮਰਨ) ਹੀ ਤੇਰੇ ਕੰਮ ਵਿਚ (ਆਉਣ ਵਾਲਾ) ਹੈ ।"},{"gurmukhi":"ਮਾਇਆਕੋਸੰਗੁਤਿਆਗੁਪ੍ਰਭਜੂਕੀਸਰਨਿਲਾਗੁ॥","meaning":"ਹੇ ਭਾਈ! ਮਾਇਆ ਦਾ ਮੋਹ ਛੱਡ ਦੇਹ, ਪਰਮਾਤਮਾ ਦੀ ਸਰਨ ਪਿਆ ਰਹੁ ।"},{"gurmukhi":"ਜਗਤਸੁਖਮਾਨੁਮਿਥਿਆਝੂਠੋਸਭਸਾਜੁਹੈ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਭਾਈ! ਦੁਨੀਆ ਦੇ ਸੁਖਾਂ ਨੂੰ ਨਾਸਵੰਤ ਸਮਝ । ਜਗਤ ਦਾ ਇਹ ਸਾਰਾ ਪਸਾਰਾ (ਹੀ) ਸਾਥ ਛੱਡ ਜਾਣ ਵਾਲਾ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਸੁਪਨੇਜਿਉਧਨੁਪਛਾਨੁਕਾਹੇਪਰਿਕਰਤਮਾਨੁ॥","meaning":"ਹੇ ਭਾਈ! ਇਸ ਧਨ ਨੂੰ ਸੁਪਨੇ (ਵਿਚ ਮਿਲੇ ਪਦਾਰਥਾਂ) ਵਾਂਗ ਸਮਝ (ਜਾਗ ਖੁਲ੍ਹਦਿਆਂ ਹੀ ਉਹ ਪਦਾਰਥ ਲੋਪ ਹੋ ਜਾਂਦੇ ਹਨ । ਦੱਸ,) ਤੂੰ ਕਾਹਦੇ ਉੱਤੇ ਅਹੰਕਾਰ ਕਰਦਾ ਹੈਂ?"},{"gurmukhi":"ਬਾਰੂਕੀਭੀਤਿਜੈਸੇਬਸੁਧਾਕੋਰਾਜੁਹੈ॥੧॥","meaning":"(ਸਾਰੀ) ਧਰਤੀ ਦਾ ਰਾਜ (ਭੀ) ਰੇਤ ਦੀ ਕੰਧ ਵਰਗਾ ਹੀ ਹੈ ।੧।"},{"gurmukhi":"ਨਾਨਕੁਜਨੁਕਹਤੁਬਾਤਬਿਨਸਿਜੈਹੈਤੇਰੋਗਾਤੁ॥","meaning":"ਹੇ ਭਾਈ! ਦਾਸ ਨਾਨਕ (ਤੈਨੂੰ ਇਹ) ਗੱਲ ਦੱਸਦਾ ਹੈ ਕਿ ਤੇਰਾ (ਤਾਂ ਇਹ ਆਪਣਾ ਮਿਥਿਆ ਹੋਇਆ) ਸਰੀਰ (ਭੀ) ਨਾਸ ਹੋ ਜਾਇਗਾ ।"},{"gurmukhi":"ਛਿਨੁਛਿਨੁਕਰਿਗਇਓਕਾਲੁਤੈਸੇਜਾਤੁਆਜੁਹੈ॥੨॥੧॥","meaning":"(ਵੇਖ, ਜਿਵੇਂ ਤੇਰੀ ਉਮਰ ਦਾ) ਕੱਲ (ਦਾ ਦਿਨ) ਛਿਨ ਛਿਨ ਕਰ ਕੇ ਬੀਤ ਗਿਆ ਹੈ, ਤਿਵੇਂ ਅੱਜ (ਦਾ ਦਿਨ ਭੀ) ਲੰਘਦਾ ਜਾ ਰਿਹਾ ਹੈ ।੨।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (9, 'ਧਨਾਸਰੀਮਹਲਾ੫ਘਰੁ੭', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਹਰਿਏਕੁਸਿਮਰਿਏਕੁਸਿਮਰਿਏਕੁਸਿਮਰਿਪਿਆਰੇ॥","meaning":"ਹੇ ਪਿਆਰੇ! ਸਦਾ ਹੀ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਕਰ ।"},{"gurmukhi":"ਕਲਿਕਲੇਸਲੋਭਮੋਹਮਹਾਭਉਜਲੁਤਾਰੇ॥ਰਹਾਉ॥","meaning":"ਇਹ ਸਿਮਰਨ) ਇਸ ਵੱਡੇ ਭਿਆਨਕ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਪਾਰ ਲੰਘਾ ਲੈਂਦਾ ਹੈ ਜਿਸ ਵਿਚ ਬੇਅੰਤ ਸੰਸਾਰਕ ਝਗੜੇ ਹਨ, ਜਿਸ ਵਿਚ ਲੋਭ ਮੋਹ (ਦੀਆਂ ਲਹਿਰਾਂ ਉਠ ਰਹੀਆਂ) ਹਨ ।ਰਹਾਉ"},{"gurmukhi":"ਸਾਸਿਸਾਸਿਨਿਮਖਨਿਮਖਦਿਨਸੁਰੈਨਿਚਿਤਾਰੇ॥","meaning":"ਹੇ ਭਾਈ! ਦਿਨ ਰਾਤ ਛਿਨ ਛਿਨ ਹਰੇਕ ਸਾਹ ਦੇ ਨਾਲ (ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਚੇਤੇ ਕਰਦਾ ਰਹੁ ।"},{"gurmukhi":"ਸਾਧਸੰਗਜਪਿਨਿਸੰਗਮਨਿਨਿਧਾਨੁਧਾਰੇ॥੧॥","meaning":"ਸਾਧ ਸੰਗਤਿ ਵਿਚ (ਬੈਠ ਕੇ) ਝਾਕਾ ਲਾਹ ਕੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਜਪਿਆ ਕਰ । ਇਹ ਨਾਮ-ਖ਼ਜ਼ਾਨਾ ਆਪਣੇ ਮਨ ਵਿਚ ਵਸਾਈ ਰੱਖ ।੧।"},{"gurmukhi":"ਚਰਨਕਮਲਨਮਸਕਾਰਗੁਨਗੋਬਿਦਬੀਚਾਰੇ॥","meaning":"ਹੇ ਪਿਆਰੇ! ਪਰਮਾਤਮਾ ਦੇ ਕੋਮਲ ਚਰਨਾਂ ਉਤੇ ਆਪਣਾ ਸਿਰ ਨਿਵਾਈ ਰੱਖ । ਗੋਬਿੰਦ ਦੇ ਗੁਣ ਆਪਣੇ ਸੋਚ-ਮੰਡਲ ਵਿਚ ਵਸਾ"},{"gurmukhi":"ਸਾਧਜਨਾਕੀਰੇਨਨਾਨਕਮੰਗਲਸੂਖਸਧਾਰੇ॥੨॥੧॥੩੧॥","meaning":"ਹੇ ਨਾਨਕ! ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ (ਆਪਣੇ ਮੱਥੇ ਉਤੇ ਲਾਇਆ ਕਰ, ਇਹ ਚਰਨ-ਧੂੜ) ਆਤਮਕ ਖ਼ੁਸ਼ੀਆਂ ਤੇ ਆਤਮਕ ਆਨੰਦ ਦੇਂਦੀ ਹੈ ।੨।੧।੩੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (10, 'ਸੋਰਠਿਮਹਲਾ੫॥', '[{"gurmukhi":"ਗੁਰਕਾਸਬਦੁਰਖਵਾਰੇ॥","meaning":"ਹੇ ਭਾਈ! ਵਿਕਾਰਾਂ ਦੇ ਟਾਕਰੇ ਤੇ) ਗੁਰੂ ਦਾ ਸ਼ਬਦ ਹੀ ਅਸਾਂ ਜੀਵਾਂ ਦਾ ਰਾਖਾ ਹੈ"},{"gurmukhi":"ਚਉਕੀਚਉਗਿਰਦਹਮਾਰੇ॥","meaning":"ਸ਼ਬਦ ਹੀ (ਸਾਨੂੰ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾਣ ਲਈ) ਸਾਡੇ ਚੁਫੇਰੇ ਪਹਿਰਾ ਹੈ"},{"gurmukhi":"ਰਾਮਨਾਮਿਮਨੁਲਾਗਾ॥","meaning":"ਗੁਰ-ਸ਼ਬਦ ਦੀ ਬਰਕਤਿ ਨਾਲ ਜਿਸ ਮਨੁੱਖ ਦਾ) ਮਨ ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਵਿਚ ਜੁੜਦਾ ਹੈ,"},{"gurmukhi":"ਜਮੁਲਜਾਇਕਰਿਭਾਗਾ॥੧॥","meaning":"ਉਸ ਪਾਸੋਂ (ਵਿਕਾਰ ਤਾਂ ਕਿਤੇ ਰਹੇ) ਜਮ (ਭੀ) ਸ਼ਰਮਿੰਦਾ ਹੋ ਕੇ ਭੱਜ ਜਾਂਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਪ੍ਰਭਜੀਤੂਮੇਰੋਸੁਖਦਾਤਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ ਜੀ! ਮੇਰੇ ਵਾਸਤੇ ਤਾਂ ਤੂੰ ਹੀ ਸੁਖਾਂ ਦਾ ਦਾਤਾ ਹੈਂ"},{"gurmukhi":"ਬੰਧਨਕਾਟਿਕਰੇਮਨੁਨਿਰਮਲੁਪੂਰਨਪੁਰਖੁਬਿਧਾਤਾ॥ਰਹਾਉ॥","meaning":"(ਹੇ ਭਾਈ! ਜੇਹੜਾ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਵਿਚ ਮਨ ਜੋੜਦਾ ਹੈ) ਸਰਬ-ਵਿਆਪਕ ਸਿਰਜਣਹਾਰ ਪ੍ਰਭੂ (ਉਸ ਦੇ ਮਾਇਆ ਦੇ ਮੋਹ ਆਦਿਕ ਦੇ ਸਾਰੇ) ਬੰਧਨ ਕੱਟ ਕੇ ਉਸ ਦੇ ਮਨ ਨੂੰ ਪਵਿਤ੍ਰ ਕਰ ਦੇਂਦਾ ਹੈ ।ਰਹਾਉ"},{"gurmukhi":"ਨਾਨਕਪ੍ਰਭੁਅਬਿਨਾਸੀ॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਅਬਿਨਾਸ਼ੀ ਪ੍ਰਭੂ"},{"gurmukhi":"ਤਾਕੀਸੇਵਨਬਿਰਥੀਜਾਸੀ॥","meaning":"(ਐਸਾ ਉਦਾਰ-ਚਿੱਤ ਹੈ ਕਿ) ਉਸ ਦੀ ਕੀਤੀ ਹੋਈ ਸੇਵਾ-ਭਗਤੀ ਖ਼ਾਲੀ ਨਹੀਂ ਜਾਂਦੀ"},{"gurmukhi":"ਅਨਦਕਰਹਿਤੇਰੇਦਾਸਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਸੇਵਕ (ਸਦਾ) ਆਤਮਕ ਆਨੰਦ ਮਾਣਦੇ ਹਨ,"},{"gurmukhi":"ਜਪਿਪੂਰਨਹੋਈਆਸਾ॥੨॥੪॥੬੮॥","meaning":"ਤੇਰਾ ਨਾਮ ਜਪ ਕੇ ਉਹਨਾਂ ਦੀ ਹਰੇਕ ਮਨੋ-ਕਾਮਨਾ ਪੂਰੀ ਹੋ ਜਾਂਦੀ ਹੈ ।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (11, 'ਕੇਦਾਰਾਮਹਲਾ੫॥', '[{"gurmukhi":"ਹਰਿਹਰਿਹਰਿਗੁਨਗਾਵਹੁ॥","meaning":"ਹੇ ਭਾਈ! ਸਦਾ ਪਰਮਾਤਮਾ ਦੇ ਗੁਣ ਗਾਂਦੇ ਰਿਹਾ ਕਰੋ ।"},{"gurmukhi":"ਕਰਹੁਕ੍ਰਿਪਾਗੋਪਾਲਗੋਬਿਦੇਅਪਨਾਨਾਮੁਜਪਾਵਹੁ॥ਰਹਾਉ॥","meaning":"ਹੇ ਗੋਪਾਲ! ਹੇ ਗੋਬਿੰਦ! (ਮੇਰੇ ਉਤੇ) ਮਿਹਰ ਕਰ, ਮੈਨੂੰ ਆਪਣਾ ਨਾਮ ਜਪਣ ਵਿਚ ਸਹਾਇਤਾ ਕਰ ।ਰਹਾਉ।"},{"gurmukhi":"ਕਾਢਿਲੀਏਪ੍ਰਭਆਨਬਿਖੈਤੇਸਾਧਸੰਗਿਮਨੁਲਾਵਹੁ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਮਨੁੱਖਾਂ ਦਾ ਮਨ ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਲਾਂਦਾ ਹੈਂ, ਉਹਨਾਂ ਨੂੰ ਤੂੰ ਹੋਰ ਹੋਰ ਵਿਸ਼ਿਆਂ ਵਿਚੋਂ ਕੱਢ ਲਿਆ ਹੈ ।"},{"gurmukhi":"ਭ੍ਰਮੁਭਉਮੋਹੁਕਟਿਓਗੁਰਬਚਨੀਅਪਨਾਦਰਸੁਦਿਖਾਵਹੁ॥੧॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੂੰ ਆਪਣਾ ਦਰਸਨ ਦੇਂਦਾ ਹੈਂ, ਗੁਰੂ ਦੇ ਬਚਨਾਂ ਦੀ ਰਾਹੀਂ ਉਹਨਾਂ ਦਾ ਭਰਮ ਉਹਨਾਂ ਦਾ ਡਰ ਉਹਨਾਂ ਦਾ ਮੋਹ ਕੱਟਿਆ ਜਾਂਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਸਭਕੀਰੇਨਹੋਇਮਨੁਮੇਰਾਅਹੰਬੁਧਿਤਜਾਵਹੁ॥","meaning":"ਹੇ ਦਇਆਲ ਪ੍ਰਭੂ! (ਮਿਹਰ ਕਰ, ਮੈਨੂੰ) ਆਪਣੀ ਭਗਤੀ (ਦੀ ਦਾਤਿ) ਬਖ਼ਸ਼ (ਮਿਹਰ ਕਰ, ਮੇਰੇ ਅੰਦਰੋਂ) ਹਉਮੈ ਦੂਰ ਕਰਾ, ਮੇਰਾ ਮਨ ਸਭਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਹੋਇਆ ਰਹੇ ।"},{"gurmukhi":"ਅਪਨੀਭਗਤਿਦੇਹਿਦਇਆਲਾਵਡਭਾਗੀਨਾਨਕਹਰਿਪਾਵਹੁ॥੨॥੪॥੬॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਭਾਈ!) ਤੁਸੀਂ ਵੱਡੇ ਭਾਗਾਂ ਨਾਲ (ਹੀ) ਪਰਮਾਤਮਾ ਦਾ ਮਿਲਾਪ ਕਰ ਸਕਦੇ ਹੋ ।੨।੪।੬।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (12, 'ਆਸਾਮਹਲਾ੫ਤਿਪਦੇ॥', '[{"gurmukhi":"ਓਹਾਪ੍ਰੇਮਪਿਰੀ॥੧॥ਰਹਾਉ॥","meaning":"(ਹੇ ਭਾਈ! ਮੈਨੂੰ ਤਾਂ) ਪਿਆਰੇ (ਪ੍ਰਭੂ) ਦਾ ਉਹ ਪ੍ਰੇਮ ਹੀ (ਚਾਹੀਦਾ ਹੈ) ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਕਨਿਕਮਾਣਿਕਗਜਮੋਤੀਅਨਲਾਲਨਨਹਨਾਹਨਹੀ॥੧॥","meaning":"(ਹੇ ਭਾਈ! ਪ੍ਰਭੂ ਦੇ ਪਿਆਰ ਦੇ ਟਾਕਰੇ ਤੇ) ਸੋਨਾ, ਮੋਤੀ, ਵੱਡੇ ਵੱਡੇ ਮੋਤੀ, ਹੀਰੇ-ਲਾਲ—ਮੈਨੂੰ ਇਹਨਾਂ ਵਿਚੋਂ ਕੋਈ ਭੀ ਚੀਜ਼ ਨਹੀਂ ਚਾਹੀਦੀ, ਨਹੀਂ ਚਾਹੀਦੀ, ।੧।"},{"gurmukhi":"ਰਾਜਨਭਾਗਨਹੁਕਮਨਸਾਦਨ॥","meaning":"(ਹੇ ਭਾਈ! ਪ੍ਰਭੂ-ਪਿਆਰ ਦੇ ਥਾਂ) ਨਾਹ ਰਾਜ, ਨਾਹ ਧਨ-ਪਦਾਰਥ, ਨਾਹ ਹੁਕੂਮਤ ਨਾਹ ਸੁਆਦਲੇ ਖਾਣੇ—"},{"gurmukhi":"ਕਿਛੁਕਿਛੁਨਚਾਹੀ॥੨॥","meaning":"ਮੈਨੂੰ ਕਿਸੇ ਚੀਜ਼ ਦੀ ਭੀ ਲੋੜ ਨਹੀਂ ।੨।"},{"gurmukhi":"ਚਰਨਨਸਰਨਨਸੰਤਨਬੰਦਨ॥","meaning":"ਹੇ ਭਾਈ! ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਸਰਨ, ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਤੇ ਨਮਸਕਾਰ—"},{"gurmukhi":"ਸੁਖੋਸੁਖੁਪਾਹੀ॥","meaning":"ਇਸ ਵਿਚ ਮੈਂ ਸੁਖ ਹੀ ਸੁਖ ਅਨੁਭਵ ਕਰਦਾ ਹਾਂ ।"},{"gurmukhi":"ਨਾਨਕਤਪਤਿਹਰੀ॥","meaning":"ਹੇ ਨਾਨਕ! ਜੇ ਪਿਆਰੇ ਪ੍ਰਭੂ ਦਾ ਪ੍ਰੇਮ ਮਿਲ ਜਾਏ"},{"gurmukhi":"ਮਿਲੇਪ੍ਰੇਮਪਿਰੀ॥੩॥੩॥੧੪੩॥","meaning":"ਤਾਂ ਉਹ ਮਨ ਵਿਚੋਂ ਤ੍ਰਿਸ਼ਨਾ ਦੀ ਸੜਨ ਦੂਰ ਕਰ ਦੇਂਦਾ ਹੈ ।੩।੩।੧੪੩।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (13, 'ਸੂਹੀਮਹਲਾ੫ਘਰੁ੩', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਸੇਵਾਥੋਰੀਮਾਗਨੁਬਹੁਤਾ॥","meaning":"ਹੇ ਭਾਈ! ਇਹ ਮੂਰਖ ਕੰਮ ਤਾਂ ਥੋੜਾ ਕਰਦਾ ਹੈ, ਪਰ ਉਸ ਦੇ ਇਵਜ਼ ਵਿਚ ਇਸ ਦੀ ਮੰਗ ਬਹੁਤ ਜ਼ਿਆਦਾ ਹੈ"},{"gurmukhi":"ਮਹਲੁਨਪਾਵੈਕਹਤੋਪਹੁਤਾ॥੧॥","meaning":"ਪ੍ਰਭੂ ਦੇ ਚਰਨਾਂ ਤਕ ਪਹੁੰਚ ਤਾਂ ਹਾਸਲ ਨਹੀਂ ਕਰ ਸਕਦਾ, ਪਰ ਆਖਦਾ ਹੈ ਕਿ ਮੈਂ (ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ) ਪਹੁੰਚਿਆ ਹੋਇਆ ਹਾਂ ।੧।"},{"gurmukhi":"ਜੋਪ੍ਰਿਅਮਾਨੇਤਿਨਕੀਰੀਸਾ॥","meaning":"ਹੇ ਭਾਈ! ਝੂਠੇ ਮੂਰਖ ਮਨੁੱਖ ਦੇ ਹਠ ਦੀ ਗੱਲ (ਸੁਣ)"},{"gurmukhi":"ਕੂੜੇਮੂਰਖਕੀਹਾਠੀਸਾ॥੧॥ਰਹਾਉ॥","meaning":"ਇਹ ਉਹਨਾਂ ਦੀ ਰੀਸ ਕਰਦਾ ਹੈ ਜੇਹੜੇ ਪਿਆਰੇ ਪ੍ਰਭੂ ਦੇ ਦਰ ਤੋਂ ਸਤਕਾਰ ਹਾਸਲ ਕਰ ਚੁਕੇ ਹਨ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਭੇਖਦਿਖਾਵੈਸਚੁਨਕਮਾਵੈ॥","meaning":"(ਹੇ ਭਾਈ! ਝੂਠਾ ਮੂਰਖ ਹੋਰਨਾਂ ਨੂੰ ਆਪਣੇ ਧਰਮੀ ਹੋਣ ਦੇ ਨਿਰੇ) ਭੇਖ ਵਿਖਾ ਰਿਹਾ ਹੈ, ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਨ ਦੀ ਕਮਾਈ ਨਹੀਂ ਕਰਦਾ"},{"gurmukhi":"ਕਹਤੋਮਹਲੀਨਿਕਟਿਨਆਵੈ॥੨॥","meaning":"ਮੂੰਹੋਂ ਆਖਦਾ ਹੈ ਕਿ ਮੈਂ ਹਜ਼ੂਰੀ ਵਿਚ ਪਹੁੰਚਿਆ ਹੋਇਆ ਹਾਂ, ਪਰ (ਪ੍ਰਭੂ-ਚਰਨਾਂ ਦੇ ਕਿਤੇ) ਨੇੜੇ ਭੀ ਨਹੀਂ ਢੁਕਿਆ ।੨।"},{"gurmukhi":"ਅਤੀਤੁਸਦਾਏਮਾਇਆਕਾਮਾਤਾ॥","meaning":"ਹੇ ਭਾਈ! ਵੇਖ ਮੂਰਖ ਦੀ ਹਠ ਦੀ ਗੱਲ! ਇਹ ਆਪਣੇ ਆਪ ਨੂੰ) ਤਿਆਗੀ ਅਖਵਾਂਦਾ ਹੈ ਪਰ ਮਾਇਆ (ਦੀ ਲਾਲਸਾ) ਵਿਚ ਮਸਤ ਰਹਿੰਦਾ ਹੈ"},{"gurmukhi":"ਮਨਿਨਹੀਪ੍ਰੀਤਿਕਹੈਮੁਖਿਰਾਤਾ॥੩॥","meaning":"ਇਸ ਦੇ) ਮਨ ਵਿਚ (ਪ੍ਰਭੂ-ਚਰਨਾਂ ਦਾ) ਪਿਆਰ ਨਹੀਂ ਹੈ, ਪਰ ਮੂੰਹੋਂ ਆਖਦਾ ਹੈ ਕਿ ਮੈਂ (ਪ੍ਰਭੂ ਦੇ ਪ੍ਰੇਮ-ਰੰਗ ਵਿਚ) ਰੰਗਿਆ ਹੋਇਆ ਹਾਂ ।੩।"},{"gurmukhi":"ਕਹੁਨਾਨਕਪ੍ਰਭਬਿਨਉਸੁਨੀਜੈ॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਪ੍ਰਭੂ! ਮੇਰੀ ਬੇਨਤੀ ਸੁਣ (ਜੀਵ ਵਿਚਾਰਾ ਕੁਝ ਕਰਨ-ਜੋਗਾ ਨਹੀਂ, ਇਹ) ਮੰਦ-ਕਰਮੀ ਹੈ, ਨਿਰਦਈ ਹੈ"},{"gurmukhi":"ਕੁਚਲੁਕਠੋਰੁਕਾਮੀਮੁਕਤੁਕੀਜੈ॥੪॥","meaning":"ਵਸ਼ਈ ਹੈ (ਫਿਰ ਭੀ ਤੇਰਾ) ਹੈ ਇਸ ਨੂੰ ਇਹਨਾਂ ਵਿਕਾਰਾਂ ਤੋਂ ਖ਼ਲਾਸੀ ਬਖ਼ਸ਼ ।੪।"},{"gurmukhi":"ਦਰਸਨਦੇਖੇਕੀਵਡਿਆਈ॥","meaning":"ਹੇ ਪੁਰਖ ਪ੍ਰਭੂ! ਤੂੰ ਸਭ ਸੁਖ ਦੇਣ-ਜੋਗ ਹੈਂ, ਤੂੰ ਪਿਆਰ-ਭਰਪੂਰ ਹੈਂ"},{"gurmukhi":"ਤੁਮ੍ਹਸੁਖਦਾਤੇਪੁਰਖਸੁਭਾਈ॥੧॥ਰਹਾਉਦੂਜਾ॥੧॥੭॥","meaning":"ਅਸਾਂ ਜੀਵਾਂ ਨੂੰ) ਇਹ ਵਡਿਆਈ ਬਖ਼ਸ਼ ਕਿ ਤੇਰਾ ਦਰਸਨ ਕਰ ਸਕੀਏ ।੧।ਰਹਾਉ ਦੂਜਾ ।੧।੭।"}]'::jsonb, 2);
